j:jelly.script:
CustomEvent.observe("list.loaded", function(table, list){
   $('sc_mobile_layout.sc_mobile_layout_cats_mtom.mobile_layout_breadcrumb').select('a').each(function(el){
      el.innerHTML = el.innerHTML.replace(/Mobile Layout.*/,"Mobile Layout");
   });
});

CustomEvent.observe("partial.page.reload", function(table, list){
   var ival;
   ival = setInterval(function() {
      var elems = $('sc_mobile_layout.sc_mobile_layout_cats_mtom.mobile_layout_breadcrumb').select('a');
      if (elems.length > 0) {
         clearInterval(ival);
         elems.each(function(el){
            el.innerHTML = el.innerHTML.replace(/Mobile Layout.*/,"Mobile Layout");
         });
      }
   }, 250);         
});
